\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{fontspec}
\setmainfont{Latin Modern Roman}
\usepackage{microtype}
\pagestyle{empty}

% ── Dark-mode Color Theme ──
\definecolor{primary}{HTML}{0B1220}       % deep navy title bar
\definecolor{secondary}{HTML}{1E293B}     % slate card bg
\definecolor{accent}{HTML}{3B82F6}        % electric blue
\definecolor{amber}{HTML}{F59E0B}         % amber
\definecolor{mint}{HTML}{10B981}          % mint green
\definecolor{bgposter}{HTML}{0B1220}      % poster background
\definecolor{cardbg}{HTML}{0F172A}        % card background
\definecolor{cardbg2}{HTML}{111827}       % alternate card
\definecolor{cardbg3}{HTML}{0A1F15}       % green-tinted card
\definecolor{cardbg4}{HTML}{1A1508}       % amber-tinted card
\definecolor{textprimary}{HTML}{F8FAFC}   % headings / key numbers
\definecolor{textsecondary}{HTML}{94A3B8} % body text
\definecolor{textgray}{HTML}{64748B}      % captions
\definecolor{gridline}{HTML}{1E293B}      % subtle borders
\definecolor{stathighlight}{HTML}{1E293B} % stat box bg

\pagecolor{bgposter}
\color{textprimary}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=8pt, parsep=2pt, topsep=4pt,
  label={\color{amber}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[4mm]
  {\fontsize{22}{28}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (left accent stripe, dark mode) ──
\tcbset{
  bluecard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbg,
    borderline west={6pt}{0pt}{accent},
    left=18pt, right=16pt, top=10pt, bottom=10pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{accent},
    coltitle=accent, colbacktitle=cardbg2,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!40},
    valign=top, drop shadow={opacity=0.25},
  },
  greencard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbg3,
    borderline west={6pt}{0pt}{mint},
    left=18pt, right=16pt, top=10pt, bottom=10pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{mint},
    coltitle=mint, colbacktitle=cardbg3!80!black,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={mint!40},
    valign=top, drop shadow={opacity=0.25},
  },
  ambercard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=cardbg4,
    borderline west={6pt}{0pt}{amber},
    left=18pt, right=16pt, top=10pt, bottom=10pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{amber},
    coltitle=amber, colbacktitle=cardbg4!80!black,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={amber!40},
    valign=top, drop shadow={opacity=0.25},
  },
  highlightcard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=accent!12!bgposter,
    borderline west={6pt}{0pt}{accent},
    left=18pt, right=16pt, top=10pt, bottom=10pt,
    fonttitle=\fontsize{32}{40}\selectfont\bfseries\color{textprimary},
    coltitle=textprimary, colbacktitle=accent!20!bgposter,
    toptitle=8pt, bottomtitle=8pt,
    titlerule=2pt, titlerule style={accent!50},
    valign=top, drop shadow={opacity=0.30},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=4mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textprimary,
  arc=0pt, boxrule=0pt,
  left=40pt, right=40pt, top=18pt, bottom=14pt,
  halign=center, valign=center,
  drop shadow={opacity=0.4}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{64}{78}\selectfont\bfseries State of Developer Ecosystem 2024}\\[10pt]
  {\fontsize{32}{40}\selectfont\color{textsecondary} Language Wars \& Rising Stars}\\[8pt]
  {\fontsize{24}{30}\selectfont\color{textgray} 23,262 developers worldwide \textbullet{} JetBrains Survey}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=secondary, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=8pt, bottom=8pt,
  valign=center, borderline south={3pt}{0pt}{accent!30},
]{name=stats, column=1, span=2, between=row3 and row5}{
  \centering
  \begin{minipage}[c]{0.23\linewidth}\centering
    \colorbox{cardbg}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{accent} 61\%}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textsecondary} JavaScript}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textgray} plateau}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \colorbox{cardbg}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{mint} 57\%}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textsecondary} Python}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textgray} steady rise}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \colorbox{cardbg}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{amber} 37\%}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textsecondary} TypeScript}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textgray} 12\%$\to$37\%}\vspace{8pt}%
    }}
  \end{minipage}\hfill
  \begin{minipage}[c]{0.23\linewidth}\centering
    \colorbox{cardbg}{\parbox{0.88\linewidth}{%
      \centering\vspace{8pt}%
      {\fontsize{52}{64}\selectfont\bfseries\color{textprimary} 18\%}\\[4pt]
      {\fontsize{22}{28}\selectfont\color{textsecondary} AI Integrations}\\[2pt]
      {\fontsize{18}{22}\selectfont\color{textgray} building now}\vspace{8pt}%
    }}
  \end{minipage}
}

% ══ COLUMN 1 ══

% Language Trajectory (centerpiece)
\posterbox[bluecard, title={Top Programming Languages (2017–2024)}]
{name=lang, column=1, between=row5 and row12}{
  \posterfig{0.96}{figures/fig_language_trajectory.png}{8-year usage trajectory — JavaScript plateaus while Python and TypeScript surge.}
  \vspace{4mm}
  \fontsize{26}{34}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{Python} climbed \textcolor{mint}{32\%$\to$57\%} in 8 years
    \item \textbf{TypeScript} 12\%$\to$37\% — strongest relative growth
    \item JavaScript holds at 61\%, but dominance is eroding
  \end{itemize}
}

% Promise Index
\posterbox[greencard, title={Rising Stars: Language Promise Index}]
{name=promise, column=1, between=row12 and row17}{
  \posterfig{0.96}{figures/fig_promise_index.png}{TypeScript (199) and Rust (198) lead the forward-looking index.}
  \vspace{4mm}
  \fontsize{26}{34}\selectfont
  \begin{itemize}[itemsep=10pt]
    \item \textbf{TypeScript at 199} signals where the ecosystem is heading
    \item Rust 198 — performance + concurrency driving intent
    \item Go and Rust are the most planned-to-adopt languages
  \end{itemize}
}

% Databases & Cloud
\posterbox[bluecard, title={Databases \& Cloud}]
{name=dbcloud, column=1, between=row17 and bottom}{
  \posterfig{0.96}{figures/fig_databases.png}{PostgreSQL climbs from 32\% to 45\% (2019–2024).}
  \vspace{3mm}
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{PostgreSQL} 32\%$\to$45\%, narrowing gap with MySQL
    \item \textbf{AWS} 46\% (down from 51\%), Azure 17\%, GCP 11\%
    \item \textbf{Docker} used locally by 49\% of developers
  \end{itemize}
}

% ══ COLUMN 2 ══

% TypeScript Breakout + AI
\posterbox[ambercard, title={The TypeScript Breakout Story}]
{name=tsbreakout, column=2, between=row5 and row10}{
  \fontsize{28}{36}\selectfont
  \colorbox{cardbg4!60!black}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{40}{50}\selectfont\bfseries\color{amber} 12\% $\boldsymbol{\to}$ 37\%}\\[4pt]
    {\fontsize{22}{28}\selectfont\color{textsecondary} TypeScript adoption (2017–2024)}\vspace{6pt}%
  }}
  \vspace{5mm}
  \begin{itemize}[itemsep=10pt]
    \item TypeScript and JavaScript \textbf{coexist}; TS is the breakout story
    \item One in six Go users is considering switching to Rust
    \item Fear of AI among developers is diminishing year over year
  \end{itemize}
}

% AI Integration
\posterbox[highlightcard, title={AI in the Developer Workflow}]
{name=ai, column=2, between=row10 and row14}{
  \fontsize{28}{36}\selectfont
  \colorbox{accent!15!bgposter}{\parbox{0.94\linewidth}{%
    \centering\vspace{6pt}%
    {\fontsize{40}{50}\selectfont\bfseries\color{textprimary} 18\%}\\[4pt]
    {\fontsize{22}{28}\selectfont\color{textsecondary} of developers build AI integrations}\vspace{6pt}%
  }}
  \vspace{5mm}
  \begin{itemize}[itemsep=10pt]
    \item \textbf{Python dominates AI/ML} — 31\% of Python devs involved
    \item \textbf{C++ surprise:} 11\% of C++ devs report active AI/ML work
    \item AI is steadily infiltrating production software
  \end{itemize}
}

% Where Applications Live
\posterbox[bluecard, title={Where Applications Live}]
{name=platforms, column=2, between=row14 and row18}{
  \posterfig{0.96}{figures/fig_platforms.png}{Desktop (53\%) still surpasses mobile (30\%).}
  \vspace{3mm}
  \fontsize{24}{32}\selectfont
  \begin{itemize}[itemsep=8pt]
    \item \textbf{Desktop 53\%} still surpasses \textbf{mobile 30\%}
    \item Browser platforms lead at 58\%
    \item Server/cloud infrastructure used by 56\% of developers
  \end{itemize}
}

% Key Takeaways
\posterbox[greencard, title={Key Takeaways}]
{name=takeaways, column=2, between=row18 and bottom}{
  \fontsize{26}{34}\selectfont
  \begin{enumerate}[itemsep=12pt]
    \item \textbf{Python is closing in on JavaScript} — the hierarchy is actively reshaping
    \item \textbf{TypeScript is the breakout story:} 12\%$\to$37\% + Promise Index \#1
    \item \textbf{AI integration (18\%)} is the forward-looking hook for 2025
  \end{enumerate}
  \vspace{4mm}
  {\fontsize{22}{28}\selectfont\color{textgray}\textit{Source: JetBrains State of Developer Ecosystem 2024}}
}

\end{tcbposter}
\end{document}
